WITH v AS (INSERT INTO project_plan_versions (project_id, id) VALUES ($1, 'v-probe-9990') RETURNING id), m AS (INSERT INTO project_plan_milestones (project_id, id, version_id, ord, title) SELECT $1, 'M9990', v.id, 9990, 'проба самотеста' FROM v RETURNING id), t AS (INSERT INTO project_plan_tasks (project_id, id, milestone_id, ord, title, size, state, kind, entity_kind, entity_name) SELECT $1, 'M9990-T1', m.id, 1, 'проба самотеста', 'S', 'closed', 'dev', 'task', 'M9990-T1' FROM m RETURNING id), d AS (INSERT INTO project_documents (project_id, content, content_hash, bytes, revision, updated_at, updated_by, entity_kind, entity_name) VALUES ($1, E'# M9990-T1 · проба самотеста\n\n| Состояние | закрыта · 9990abc |\n', 'probe-selftest', 60, 1, (extract(epoch from now()) * 1000)::bigint, 'probe-selftest', 'task', 'M9990-T1') RETURNING entity_kind, entity_name), h AS (INSERT INTO task_state (project_id, task_id, state, seen_at) SELECT $1, t.id, 'not_started', (extract(epoch from now()) * 1000)::bigint FROM t RETURNING task_id) INSERT INTO project_document_fields (project_id, section_ord, ord, name, shape, value_raw, value, entity_kind, entity_name) SELECT $1, 0, 0, 'Состояние', 'row', ' закрыта · 9990abc ', 'закрыта · 9990abc', d.entity_kind, d.entity_name FROM d
